1	#ifndef SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
2	#define SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/fused_decoder_megakernel.cuh — PHASE 1 of the TRUE L3 fused
5	// megakernel. ONE persistent kernel per training step runs the REAL transformer-
6	// decoder forward+backward AND the AdamW optimizer math, separated only by
7	// in-kernel grid barriers — real model math, real optimizer math, ZERO
8	// intermediate kernel launches.
9	//
10	// This composes:
11	//   * the REAL decoder fwd/bwd stages (model_stages_decoder.cuh — transcribed
12	//     line-for-line from the verified PyTorch oracle, asserted bit-identical to
13	//     autograd, and structurally mirrored on CPU),
14	//   * the existing persistent substrate (megakernel_common.cuh: task queue, the
15	//     hand-built sense-reversing GridBarrier),
16	//   * the existing REAL optimizer tail (opt_components.cuh::apply_optimizer<Opt>).
17	//
18	// STAGE / BARRIER LAYOUT (5 phases, 4 grid barriers — see the per-stage comments):
19	//   P0  zero the per-CTA grad-partial workspace + per-CTA loss slots (each CTA
20	//       zeroes its OWN slice — no cross-CTA contention, no host memset needed).
21	//   --- grid barrier (B0): all partials zeroed before any accumulation ---
22	//   P1  BATCH-PARALLEL fwd+bwd: each CTA owns a FIXED contiguous batch slice
23	//       (by blockIdx.x), processes its samples ONE AT A TIME (CTA-cooperative),
24	//       accumulating each sample's weight-grad contribution into the CTA's OWN
25	//       partial buffer (gw + cta*total) with a single-owner-thread-per-element
26	//       rule (no atomics → deterministic), and summing its slice's NLL (fp32)
27	//       into the CTA's loss slot.
28	//   --- grid barrier (B1): all CTAs' partials + loss complete ---
29	//   P2  DETERMINISTIC cross-CTA reduce: sum partial[0..nCTA) in ASCENDING CTA
30	//       index into the global `grad` buffer (no float atomics; the per-element
31	//       summation ORDER is fixed, so the work-steal queue MAY pick who reduces
32	//       which element-range — determinism is in the order, not the picker). The
33	//       loss slots are summed in fp64 → one device float (loss/B), by CTA 0.
34	//   --- grid barrier (B2): reduced grad ready in global ---
35	//   P3  the existing apply_optimizer<AdamW> tail consumes the reduced grad
36	//       in-place over the flat param (work-steal queue over the 30 tensors).
37	//   (no barrier after P3 — kernel exits; the step is complete.)
38	//
39	// HONESTY: no placeholder math anywhere on this path. fp32 compute is the
40	// correctness baseline; a bf16-compute follow-up would be a flag defaulting to
41	// THIS fp32 path (not yet wired — see the report).
42	// ============================================================================
43	
44	#include "csrc/fused/megakernel_common.cuh"
45	#include "csrc/fused/sm_90/opt_components.cuh"
46	#include "csrc/fused/sm_90/decoder_layout.cuh"
47	#include "csrc/fused/sm_90/model_stages_decoder.cuh"
48	#include "csrc/backends/cuda/sm_90/warp_specialize.cuh"
49	
50	#include <cuda_runtime.h>
51	#include <cstdint>
52	#include <cassert>
53	
54	// ============================================================================
55	//  SG_TUNED_GEMM_IMPL — the per-cell GEMM-engine selector (DESIGN-TC-PIPELINE.md
56	//  §9 / the owner "BOTH paths compiled, the tuner picks" directive). The scalar
57	//  fp32 owner-computes path (model_stages_decoder.cuh) and the bf16 wgmma
58	//  tensor-core path (model_stage_decoder_tc.cuh) are compiled ALONGSIDE each
59	//  other; the kernel-autotuner injects -DSG_TUNED_GEMM_IMPL=<token> per-TU to
60	//  pick one. Absent the macro, the SCALAR path compiles verbatim (CONTRACT
61	//  rule 3: an untuned build is a correct build) — this is the shipped default
62	//  and the path all of test_megakernel_vs_eager.py's L3-REAL decoder gates
63	//  exercise; adding this seam must leave those numbers BIT-IDENTICAL.
64	//
65	//  Tokens are integers (the C preprocessor cannot compare strings, and the
66	//  autotuner's -D injection passes an integer literal):
67	//      SG_GEMM_IMPL_SCALAR = 0   (default; the verbatim fp32 path below)
68	//      SG_GEMM_IMPL_WGMMA  = 1   (the Fork-B bf16 tensor-core cell)
69	//
70	//  WGMMA-PATH STATUS (honest, no-suppression — MEMORY.md "fix components, never
71	//  disable them"): the validated unit today is the GEMM ENGINE
72	//  (model_stage_decoder_tc.cuh::tc_gemm_block_unpipelined + the wgmma.cuh /
73	//  tile_pipeline.cuh substrate), silicon-gated 13/13 by test_decoder_tc.py
74	//  (fwd/dX/dW vs the bf16-rounded fp64 oracle, A=I localizations exactly 0.0,
75	//  dW A/A/A bit-identical) on a validated 18/18 substrate. The full Fork-B
76	//  fwd+bwd CELL DRIVER (the phase-restructured P0→P1(fwd+bwd, acts→HBM)→
77	//  optimizer megakernel that REPLACES the body below) is DESIGN §11 work item
78	//  R2.3 and is NOT yet authored. Selecting the wgmma token therefore FAILS THE
79	//  COMPILE LOUDLY (the #error below) rather than silently shipping the scalar
80	//  body under a wgmma name — a wgmma-requested cell that secretly ran scalar
81	//  would be exactly the functionality suppression the owner forbids. The seam
82	//  is in place and dormant; wiring the driver into it is the bounded next step.
83	// ============================================================================
84	#define SG_GEMM_IMPL_SCALAR 0
85	#define SG_GEMM_IMPL_WGMMA  1
86	#ifndef SG_TUNED_GEMM_IMPL
87	#define SG_TUNED_GEMM_IMPL SG_GEMM_IMPL_SCALAR
88	#endif
89	#if (SG_TUNED_GEMM_IMPL != SG_GEMM_IMPL_SCALAR) && \
90	    (SG_TUNED_GEMM_IMPL != SG_GEMM_IMPL_WGMMA)
91	#error "SG_TUNED_GEMM_IMPL must be SG_GEMM_IMPL_SCALAR (0) or SG_GEMM_IMPL_WGMMA (1)"
92	#endif
93	// WGMMA-PATH (R2.3, NOW LANDED): the Fork-B tensor-core CELL DRIVER. Selecting
94	// the wgmma token pulls in the validated GEMM engine (model_stage_decoder_tc
95	// .cuh, test_decoder_tc.py 13/13 on the 18/18 substrate) and the
96	// phase-restructured fwd+bwd+AdamW persistent kernel below (fused_decoder_
97	// megakernel_tc / launch_fused_decoder_megakernel_tc). The scalar default path
98	// is UNCHANGED and its gates stay bit-identical; this is a PARALLEL kernel.
99	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
100	#include "csrc/fused/sm_90/model_stage_decoder_tc.cuh"
101	// STAGED-optimizer in-kernel precompute stages (Prodigy d-reduction, …). Pulls in
102	// the canonical prodigy.h reduction math + the deterministic block reductions; the
103	// TC megakernel's Prodigy branch drives prodigy_precompute_reduce_phaseA + an EMA
104	// d-update owner block between B2 and P3. Included only under the wgmma token (the
105	// scalar default path has no STAGED tail).
106	#include "csrc/fused/sm_90/opt_stages_precompute.cuh"
107	#endif
108	
109	namespace sg { namespace fused { namespace sm90 {
110	
111	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
112	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
113	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
114	template <OptId Opt>
115	__device__ __forceinline__ FusedOptState
116	rebase_state(const FusedOptState& s, int64_t off) {
117	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
118	    if (t.exp_avg)    t.exp_avg    += off;
119	    if (t.exp_avg_sq) t.exp_avg_sq += off;
120	    if (t.ema)        t.ema        += off;
121	    if (t.sam_dir)    t.sam_dir    += off;
122	    if (t.s_track)    t.s_track    += off;
123	    if (t.mu)         t.mu         += off;
124	    if (t.orth)       t.orth       += off;
125	    if (t.smart_grad) t.smart_grad += off;
126	    if (t.param_init) t.param_init += off;   // Prodigy trajectory anchor p0
127	    return t;
128	}
129	
130	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
131	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
132	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
133	//
134	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
135	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
136	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
137	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
138	// total == kDecTotalElems == 422755.
139	
140	struct DecoderTokenCtx {
141	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
142	    const int* targets;  // [B]       int32 target ids
143	    int        B;        // batch size (full-batch in the race ≈ 4191)
144	    float*     workspace; // grad partials + loss partials + reduced loss
145	    float*     loss_out;  // device float the kernel writes the mean loss into
146	};
147	
148	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
149	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
150	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
151	//    the launcher is unchanged). ────────────────────────────────────────────────
152	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
153	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
154	// the reduce + optimizer phases read them directly. This also lets the host side
155	// (dispatch.cpp) avoid building any layout tensors.
156	template <OptId Opt>
157	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
158	fused_decoder_megakernel(PersistentContext ctx,
159	                         float* __restrict__ params,
160	                         DecoderTokenCtx tok,
161	                         float* __restrict__ grad,        // reduced grad [total]
162	                         float lr, int step, FusedOptState st) {
163	    __shared__ DecSampleSmem sm;
164	    GridBarrier bar = ctx.barrier();
165	    const int cta = blockIdx.x;
166	    const int nCTA = (int)ctx.n_ctas;
167	    const int64_t total = kDecTotalElems;
168	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
169	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
170	
171	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
172	    const int wg = threadIdx.x / 128;
173	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
174	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
175	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
176	
177	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
178	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
179	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
180	    bar.sync();   // B0
181	
182	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
183	    DecWeights w = dec_bind(params);
184	    DecGrad g = dec_bind_grad(my_partial);
185	    // Even split with remainder to the low CTAs (contiguous, deterministic).
186	    const int B = tok.B;
187	    const int base = B / nCTA, rem = B % nCTA;
188	    const int b0 = cta * base + (cta < rem ? cta : rem);
189	    const int cnt = base + (cta < rem ? 1 : 0);
190	    const int b1 = b0 + cnt;
191	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
192	    __shared__ int tgt_s;
193	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
194	    for (int b = b0; b < b1; ++b) {
195	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
196	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
197	        __syncthreads();
198	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
199	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
200	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
201	        __syncthreads();   // sample boundary: all grad writes done before reuse
202	    }
203	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
204	    bar.sync();   // B1: all CTA partials + loss slots complete
205	
206	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
207	    //    (one task = one parameter tensor; sum its elements across CTAs in
208	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
209	    //    the result is deterministic regardless of which CTA grabs the task. ────
210	    {
211	        __shared__ int task_slot;
212	        TaskQueue q = ctx.queue();
213	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
214	             t = q.next_block(&task_slot)) {
215	            const int n = kDecSizes[t];
216	            const int64_t off = (int64_t)kDecOffsets[t];
217	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
218	                float acc = 0.0f;
219	                // ascending CTA index → fixed fp32 summation order (deterministic).
220	                for (int c = 0; c < nCTA; ++c)
221	                    acc += tok.workspace[(int64_t)c * total + off + i];
222	                grad[off + i] = acc;
223	            }
224	        }
225	    }
226	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
227	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
228	    if (cta == 0 && threadIdx.x == 0) {
229	        double s = 0.0;
230	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
231	        float mean = (float)(s / (double)B);
232	        *tok.loss_out = mean;
233	    }
234	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
235	
236	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
237	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
238	    st.lr = lr;
239	    {
240	        __shared__ int task_slot;
241	        TaskQueue q = ctx.queue();
242	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
243	             t = q.next_block(&task_slot)) {
244	            const int n = kDecSizes[t];
245	            const int64_t off = (int64_t)kDecOffsets[t];
246	            const FusedOptState ts = rebase_state<Opt>(st, off);
247	            float* __restrict__ p = params + off;
248	            const float* __restrict__ gg = grad + off;
249	            for (int i = threadIdx.x; i < n; i += blockDim.x)
250	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
251	        }
252	    }
253	}
254	
255	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
256	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
257	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
258	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
259	template <OptId Opt>
260	cudaError_t launch_fused_decoder_megakernel(
261	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
262	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
263	    int dev = 0;
264	    cudaError_t err = cudaGetDevice(&dev);
265	    if (err != cudaSuccess) return err;
266	    int n_sms = 0;
267	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
268	    if (err != cudaSuccess) return err;
269	
270	    int occ = 0;
271	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
272	        &occ, (const void*)&fused_decoder_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
273	        /*dynamicSMemBytes=*/0);
274	    if (err != cudaSuccess) return err;
275	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
276	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
277	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
278	    assert(occ >= 1 &&
279	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
280	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
281	           "reduce footprint or fall back to the L1 per-op path.");
282	    if (occ < 1) return cudaErrorLaunchOutOfResources;
283	
284	    const unsigned launch_ctas = (unsigned)n_sms;
285	    ctx.n_ctas = launch_ctas;
286	
287	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
288	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
289	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
290	
291	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
292	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
293	        ctx, params, tok, grad, lr, step, st);
294	    return cudaGetLastError();
295	}
296	
297	// ════════════════════════════════════════════════════════════════════════════
298	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, R2.3). Compiled only under
299	//  the wgmma token; the scalar path above is untouched.
300	// ════════════════════════════════════════════════════════════════════════════
301	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
302	
303	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
304	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
305	// path's asymmetric setmaxnreg (dealloc<32> on WG0) — that would STARVE the MMA
306	// warpgroup (WG0 issues the wgmma; a 128-wide accumulator needs 64 fp32 regs/
307	// thread). The validated selftest ran no split; we match it.
308	#define SG_TC_MEGA_BLOCK 256
309	
310	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
311	//    + the 256-float reduction slot. 16B-aligned. N = SG_TUNED_TILE_N. The 9 dW
312	//    specs live here too (identical for all threads → shared, not per-thread
313	//    stack: keeps the launch's local-memory reservation small so the persistent
314	//    kernel places on a memory-tight GPU). ──
315	struct DecTcSmem {
316	    // kDecTcStages A(64×16) + kDecTcStages B(N×16) bf16 tiles — the GEMM K-loop
317	    // double-buffer ring (slot s at sA + s*64*16 / sB + s*N*16). At S=2 + N=128
318	    // the ring is 2·(2KB+4KB)=12KB; DecTcSmem total ~13.5KB ≪ the 48KB static cap.
319	    __nv_bfloat16 sA[dectc::kDecTcStages * 64 * 16];
320	    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
321	    float red[256];
322	    dectc::DecDwSpec spec[9];
323	};
324	
325	// ── TC workspace layout (carved from tok.workspace; the host sizes it for the
326	//    TC path — see dec_tc_workspace_floats). Regions (float units):
327	//      [0 .. acts_f)                      : DecActs bf16 region (reinterpreted)
328	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
329	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
330	//      [.. + nCTA)                        : per-CTA loss slots (f32)
331	//      [.. + 1)                           : reduced scalar loss (host reads it)
332	//    acts_f = ceil(acts_bf16 / 2). ──
333	__host__ __device__ __forceinline__ int64_t dec_tc_acts_floats(int T, int B) {
334	    // mirror dectc::dec_acts_bind's running offset (bf16 elems) → floats.
335	    const int64_t d = dec::kD, dff = dec::kDff, V = dec::kVocab, L = dec::kLayers;
336	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
337	    int64_t bf = 0;
338	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
339	    bf += (int64_t)B * d + (int64_t)B * V + Td;     // X_hn + dY_logits + dh0
340	    return (bf + 1) / 2;
341	}
342	// dW split-K partial floats (0 when G==1 → no extra scratch, single-CTA path).
343	__host__ __device__ __forceinline__ int64_t dec_tc_dw_part_floats() {
344	    return (dectc::kDecDwSplitK > 1) ? dectc::dec_dw_part_floats(dectc::kDecDwSplitK) : 0;
345	}
346	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). The Prodigy
347	// stage publishes per-CTA (r,s) slots (2*nCTA) + a reduced-d slot (1) — an owner-
348	// computes tree (opt_stages_precompute.cuh), NO float atomic. Sized for the
349	// LARGEST nCTA (one CTA/SM = #SMs); tiny (≤ 2*132+1 ≈ 1 KB) and carved
350	// UNCONDITIONALLY so the opt-agnostic host launcher (dec_tc_launcher_scratch)
351	// allocates one workspace that fits every OptId. Unused by AdamW/Lion/… (their
352	// P3 never touches this region), so adding it leaves those cells byte-identical.
353	__host__ __device__ __forceinline__ int64_t dec_tc_opt_reduce_floats(int nCTA) {
354	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
355	}
356	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch. IDENTICAL in
357	//    shape to the vit twin (vit_tc_muon_floats): the NS chain runs ONE 2D weight at
358	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
359	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
360	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
361	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
362	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
363	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
364	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
365	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
366	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
367	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
368	    return (int64_t)4 * dectc::kDecMuonMaxNumel
369	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
370	         + nCTA + 1;
371	}
372	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
373	    return dec_tc_acts_floats(T, B)
374	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
375	         + (int64_t)nCTA * dectc::kLnVecElems
376	         + nCTA + 1
377	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
378	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
379	         + dec_tc_muon_floats(nCTA);          // STAGED-opt (Muon) NS per-matrix scratch
380	}
381	
382	template <OptId Opt>
383	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
384	fused_decoder_megakernel_tc(PersistentContext ctx,
385	                            float* __restrict__ params,
386	                            DecoderTokenCtx tok,
387	                            float* __restrict__ grad,
388	                            float lr, int step, FusedOptState st) {
389	    __shared__ DecTcSmem sm;
390	    GridBarrier bar = ctx.barrier();
391	    const int cta = blockIdx.x;
392	    const int nCTA = (int)ctx.n_ctas;
393	    const int B = tok.B;
394	    const int T = B * dec::kSeq;
395	
396	    // Workspace partition.
397	    float* ws = tok.workspace;
398	    const int64_t acts_f = dec_tc_acts_floats(T, B);
399	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
400	    float* scratch_base = ws + acts_f;
401	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
402	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
403	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
404	    float* loss_out   = loss_part + nCTA;
405	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
406	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
407	    float* dw_part    = loss_out + 1;
408	    const int kDwG    = dectc::kDecDwSplitK;
409	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
410	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
411	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
412	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
413	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
414	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
415	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
416	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
417	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
418	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
419	
420	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
421	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
422	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
423	
424	    DecWeights w = dec_bind(params);
425	
426	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
427	    //    written-once → no pre-zero). ──
428	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
429	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
430	    bar.sync();   // B0
431	
432	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
433	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
434	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
435	    const int nrows_tile = dectc::kTileM;
436	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
437	    float nll_acc = 0.0f;
438	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
439	        const int g0 = ti * nrows_tile;
440	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
441	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
442	                                              sm.sA, sm.sB, sm.red);
443	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
444	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
445	        if (threadIdx.x == 0) nll_acc += nll;
446	        __syncthreads();
447	    }
448	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
449	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
450	
451	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
452	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
453	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
454	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
455	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
456	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
457	    __syncthreads();
458	    dectc::DecDwSpec* spec = sm.spec;
459	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
460	    if (kDwG > 1) {
461	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
462	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
463	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
464	            const int gt = item / kDwG, kc = item % kDwG;
465	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
466	        }
467	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
468	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
469	    } else {
470	        for (int gt = cta; gt < n_dw; gt += nCTA)
471	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
472	    }
473	    dectc::dectc_dw_biases(spec, grad);
474	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
475	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
476	    // Loss reduce (fp64) by CTA 0.
477	    if (cta == 0 && threadIdx.x == 0) {
478	        double s = 0.0;
479	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
480	        *tok.loss_out = (float)(s / (double)B);
481	    }
482	    (void)loss_out;
483	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
484	
485	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
486	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
487	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
488	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
489	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
490	    //    deterministic ascending reduction (no float atomics): each CTA sums a
491	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
492	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
493	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
494	    //    + the eager-side clip must both see the unclipped reduced grad); the
495	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
496	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
497	    if constexpr (Opt == OptId::GrokAdamW) {
498	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
499	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
500	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
501	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
502	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
503	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
504	        const int64_t total = kDecTotalElems;
505	        const int64_t base = total / nCTA, rem = total % nCTA;
506	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
507	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
508	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
509	        float tsum = 0.0f;
510	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
511	            const float gv = grad[e0 + i];
512	            tsum += gv * gv;
513	        }
514	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
515	        float* red = sm.red;
516	        red[threadIdx.x] = tsum;
517	        __syncthreads();
518	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
519	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
520	            __syncthreads();
521	        }
522	        if (threadIdx.x == 0) sq_part[cta] = red[0];
523	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
524	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
525	        if (cta == 0 && threadIdx.x == 0) {
526	            double ss = 0.0;
527	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
528	            const float total_norm = sqrtf((float)ss);
529	            float coef = 1.0f;
530	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
531	                coef = st.grad_clip / (total_norm + 1e-6f);
532	            *coef_bc = coef;
533	        }
534	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
535	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
536	    }
537	
538	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. The apply tail
539	    //    (apply_optimizer<Prodigy>) reads st.d_factor (the effective LR scale d),
540	    //    a GLOBAL reduction over EVERY element of EVERY tensor. We compute it here,
541	    //    BYTE-FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh:465-
542	    //    544, the order prodigy.py → _ops.prodigy_fused_step actually executes):
543	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state
544	    //                slot would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits
545	    //                _d_lr=d0=1e-6, so seed it here, the grokfast-style step-1 fix)
546	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
547	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
548	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
549	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
550	    //    DETERMINISM (COMPONENT_CONTRACT): NO float atomic. Each CTA publishes its
551	    //    (r,s) into per-CTA slots (opt_reduce) → grid barrier → CTA0 owner-sums in
552	    //    ascending index order → writes d back to the persisted slot + a broadcast
553	    //    slot. The decay is on the persisted SCALARS (not the per-CTA partials):
554	    //    the work-steal queue reassigns tensors to CTAs across steps, so a per-CTA
555	    //    EMA is undefined — the live form is a scalar EMA (prodigy_sm90.cuh:488).
556	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
557	    if constexpr (Opt == OptId::Prodigy) {
558	        PrecomputeWorkspace pw{};
559	        pw.prodigy_partials = opt_reduce;            // [r slots | s slots]
560	        pw.prodigy_d        = opt_reduce + 2 * nCTA; // reduced-d broadcast slot
561	        // d_prev: persisted d_lr (slot 2 of prodigy_persist), or d0 at step 1.
562	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
563	        st.d_factor = d_prev;   // phaseA reads st.d_factor as d_prev (prodigy.h)
564	        // Phase A: each CTA accumulates Σ d_prev²·<g,p0−p> / Σ d_prev²·|g| over its
565	        // claimed tensors → per-CTA (r,s) slots. Drains the task queue (the P3
566	        // re-drain below needs a queue reset, done at the barrier).
567	        prodigy_precompute_reduce_phaseA(ctx, params, st.param_init, grad,
568	                                         kDecSizes, kDecOffsets, d_prev, pw);
569	        bar.sync_reset(ctx.g_next_task);   // B2.6a: slots published; reset queue for P3
570	        // Owner block (CTA0 thread0): EMA decay + accumulate + d_coef + update_d,
571	        // byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
572	        if (cta == 0 && threadIdx.x == 0) {
573	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
574	            for (int c = 0; c < nCTA; ++c) {
575	                r_step += pw.prodigy_partials[c];
576	                s_step += pw.prodigy_partials[nCTA + c];
577	            }
578	            // Decay persisted scalars by beta3, then add this step's reduction.
579	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
580	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
581	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
582	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
583	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
584	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
585	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
586	            st.prodigy_persist[1] = s_ema;
587	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
588	            pw.prodigy_d[0]       = d_new;          // broadcast to all CTAs
589	        }
590	        bar.sync();   // B2.6b: d visible to every CTA before the apply
591	        st.d_factor = pw.prodigy_d[0];              // the reduced d the tail reads
592	    }
593	
594	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
595	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
596	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
597	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
598	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
599	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
600	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
601	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
602	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
603	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
604	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
605	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
606	    //    muon_update_step); the matmuls are the cited new device code (the eager path
607	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
608	    //    (no extra barriers / work).
609	    if constexpr (Opt == OptId::Muon) {
610	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
611	        PrecomputeWorkspace pw{};
612	        pw.muon_X            = muon_base;
613	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
614	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
615	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
616	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
617	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
618	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
619	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
620	        const int   ns_steps = 5;                 // bindings.cpp default
621	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
622	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
623	            const int rows = M.rows, cols = M.cols;
624	            const int64_t numel = (int64_t)rows * cols;
625	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
626	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
627	            pw.muon_buf = st.exp_avg + off;
628	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
629	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
630	            bar.sync();
631	            muon_norm_reduce_phaseB(ctx, pw);
632	            bar.sync();
633	            muon_scale_X(numel, pw);
634	            bar.sync();
635	            // NS iterations. After each combine, orth holds the new iterate; swap so
636	            // the next iteration reads it as X. ns_steps swaps → final result is in
637	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
638	            for (int s = 0; s < ns_steps; ++s) {
639	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
640	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
641	                bar.sync();
642	                // AX = A X   (M=rows,N=cols,K=rows).
643	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
644	                bar.sync();
645	                // AAX = A (AX) (M=rows,N=cols,K=rows).
646	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
647	                bar.sync();
648	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
649	                bar.sync();
650	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
651	            }
652	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
653	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
654	            const float neg_lr_scale = -lr * scale;
655	            const float decay_factor = 1.0f - lr * st.wd;
656	            float* __restrict__ p = params + off;
657	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
658	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
659	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
660	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
661	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
662	        }
663	    }
664	
665	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
666	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
667	    st.lr = lr;
668	    {
669	        __shared__ int task_slot;
670	        TaskQueue q = ctx.queue();
671	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
672	             t = q.next_block(&task_slot)) {
673	            const int n = kDecSizes[t];
674	            const int64_t off = (int64_t)kDecOffsets[t];
675	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
676	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
677	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
678	            if constexpr (Opt == OptId::Muon) {
679	                if (dectc::dec_is_muon_2d(t)) continue;
680	            }
681	            FusedOptState ts = rebase_state<Opt>(st, off);
682	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
683	            //     t == the tensor's flat named_parameters() layer index (the
684	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
685	            //     enumeration order, so t IS the eager layer index). bc1 must be
686	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
687	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
688	            if constexpr (Opt == OptId::GrokAdamW) {
689	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
690	                ts.beta1 = b1;
691	                ts.bc1   = 1.0f - powf(b1, (float)step);
692	            }
693	            float* __restrict__ p = params + off;
694	            const float* __restrict__ gg = grad + off;
695	            if constexpr (Opt == OptId::Muon) {
696	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
697	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
698	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
699	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
700	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
701	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
702	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
703	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
704	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
705	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
706	                // adamw_step with the aux hyperparameters — IDENTICAL to the vit twin.
707	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
708	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
709	                for (int i = threadIdx.x; i < n; i += blockDim.x)
710	                    algo::adamw_step<float, float>(
711	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
712	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
713	                        a_bc1, a_bc2, (int64_t)i);
714	            } else {
715	                for (int i = threadIdx.x; i < n; i += blockDim.x)
716	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
717	            }
718	        }
719	    }
720	}
721	
722	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
723	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
724	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
725	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
726	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
727	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
728	// nCTA (the dW/embedding owner maps are functions of nCTA).
729	template <OptId Opt>
730	cudaError_t launch_fused_decoder_megakernel_tc(
731	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
732	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
733	        int ncta_cap = 0) {
734	    int dev = 0;
735	    cudaError_t err = cudaGetDevice(&dev);
736	    if (err != cudaSuccess) return err;
737	    int n_sms = 0;
738	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
739	    if (err != cudaSuccess) return err;
740	
741	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
742	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
743	    // can't place one block/SM, REFUSE (the grid barrier would hang).
744	    int occ = 0;
745	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
746	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
747	        /*dynamicSMemBytes=*/0);
748	    if (err != cudaSuccess) return err;
749	    if (occ < 1) return cudaErrorLaunchOutOfResources;
750	
751	    unsigned launch_ctas = (unsigned)n_sms;
752	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
753	    ctx.n_ctas = launch_ctas;
754	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
755	    // AND it guarantees full token tiles for the projections). NO G-divisibility
756	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
757	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
758	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
759	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
760	
761	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
762	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
763	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
764	
765	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
766	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
767	        ctx, params, tok, grad, lr, step, st);
768	    return cudaGetLastError();
769	}
