816	// Attention BACKWARD over a tile (the oracle's 3-pass form, tile-batched).
817	// Reads qkv (bf16), attn weights, and dctx [nrows,d] fp32; writes dqkv [nrows,3d]
818	// fp32 into `dqkv_out`. dsc is the per-CTA dscores scratch. Mirror of
819	// dec_backward_sample's attention block (A: dv, B: dscores, C: dq/dk), looped
820	// over the tile's samples. scale = 1/sqrt(dh).
821	__device__ __forceinline__ void dectc_attn_bwd_tile(
822	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
823	        const float* __restrict__ dctx, int nrows,
824	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
825	    const int nsamp = nrows / dec::kSeq;
826	    const float scale = dec::attn_scale();
827	    // A: dv[kj] = Σ_{qi>=kj} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t).
828	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
829	        const int si  = r / (dec::kSeq * dec::kHeads * dec::kDhead);
830	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
831	        const int kj  = rem / (dec::kHeads * dec::kDhead);
832	        rem = rem % (dec::kHeads * dec::kDhead);
833	        const int hh  = rem / dec::kDhead, t = rem % dec::kDhead;
834	        const int qoff = hh * dec::kDhead;
835	        const int rbase = si * dec::kSeq;
836	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
837	        float acc = 0.0f;
838	        #pragma unroll
839	        for (int qi = kj; qi < dec::kSeq; ++qi)
840	            acc += aw[qi * dec::kSeq + kj] * dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t];
841	        dqkv_out[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t] = acc;   // dv block
842	    }
843	    __syncthreads();
844	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale, masked kj>qi → 0.
845	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
846	    for (int r = threadIdx.x; r < nsamp * dec::kHeads * dec::kSeq; r += blockDim.x) {
847	        const int si = r / (dec::kHeads * dec::kSeq);
848	        int rem = r % (dec::kHeads * dec::kSeq);
849	        const int hh = rem / dec::kSeq, qi = rem % dec::kSeq;
850	        const int qoff = hh * dec::kDhead;
851	        const int rbase = si * dec::kSeq;
852	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;
853	        float datt[dec::kSeq];
854	        #pragma unroll
855	        for (int kj = 0; kj < dec::kSeq; ++kj) {
856	            if (kj > qi) { datt[kj] = 0.0f; continue; }
857	            float acc = 0.0f;
858	            #pragma unroll
859	            for (int t = 0; t < dec::kDhead; ++t)
860	                acc += dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t]
861	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t]);
862	            datt[kj] = acc;
863	        }
864	        float dot = 0.0f;
865	        #pragma unroll
866	        for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * aw[qi * dec::kSeq + kj];
867	        float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
868	        #pragma unroll
869	        for (int kj = 0; kj < dec::kSeq; ++kj) {
870	            float a = aw[qi * dec::kSeq + kj];
871	            ds[kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale : 0.0f;
872	        }
873	    }
874	    __syncthreads();
875	    // C: dq[qi] = Σ_kj ds[qi,kj]*k[kj]; dk[kj] = Σ_qi ds[qi,kj]*q[qi]. Owner: (sample,pos,head,t).
876	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
877	        const int si = r / (dec::kSeq * dec::kHeads * dec::kDhead);
878	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
879	        const int pos = rem / (dec::kHeads * dec::kDhead);
880	        rem = rem % (dec::kHeads * dec::kDhead);
881	        const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
882	        const int qoff = hh * dec::kDhead;
883	        const int rbase = si * dec::kSeq;
884	        const float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
885	        float dq = 0.0f, dk = 0.0f;
886	        #pragma unroll
887	        for (int kj = 0; kj < dec::kSeq; ++kj) {
888	            dq += ds[pos * dec::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff + t]);
889	            dk += ds[kj * dec::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + qoff + t]);
890	        }
891	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + qoff + t] = dq;             // dq block
892	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + dec::kD + qoff + t] = dk;   // dk block
893	    }
894	    __syncthreads();
895	}
