897	// ════════════════════════════════════════════════════════════════════════
898	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
899	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
900	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
901	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
902	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
903	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
904	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
905	//
906	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
907	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
908	//  is the dedicated scratch.dh.
909	// ════════════════════════════════════════════════════════════════════════
910	__device__ void dectc_backward_tile(
911	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
912	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
913	        float* __restrict__ lnvec, float* __restrict__ work2,
914	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
915	    const int nsamp = nrows / dec::kSeq;
916	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
917	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
918	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
919	    for (int li = 0; li < dec::kLayers; ++li) {
920	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
921	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
922	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
923	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
924	    }
925	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
926	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
927	
928	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
929	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
930	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
931	    // First zero scratch.dh for the whole tile (only last positions get grad).
932	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
933	    __syncthreads();
934	    for (int si = 0; si < nsamp; ++si) {
935	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
936	        const int gs = si_global(g0, si);
937	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
938	        int tgt = tgt_ids[gs];
939	        // softmax of cached logits.
940	        float lmax = -CUDART_INF_F;
941	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
942	        lmax = dec_block_max(lmax, red);
943	        float es = 0.0f;
944	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
945	        es = dec_block_sum(es, red);
946	        float inv_es = 1.0f / es;
947	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
948	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
949	            float smo = __expf(lg[o] - lmax) * inv_es;
950	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
951	            lg[o] = dl;
952	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
953	        }
954	        __syncthreads();
955	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
956	        // Then final-norm bwd of that single row → scratch.dh[rlast].
957	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
958	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
959	            float dhn = 0.0f;
960	            for (int o = 0; o < dec::kVocab; ++o)
961	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
962	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
963	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
964	        }
965	        __syncthreads();
966	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
967	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
968	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
969	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
970	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
971	        }
972	        __syncthreads();
973	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
974	        {
975	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
976	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
977	            float sda = 0.0f, sdax = 0.0f;
978	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
979	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
980	            }
981	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
982	            float iv = sc.fni[rlast];
983	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
984	                float dxhat = dyr[j] * w.norm_w[j];
985	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
986	            }
987	            __syncthreads();
988	        }
989	    }
990	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
991	
992	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
993	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
994	    //    recompute). ──
995	    for (int li = dec::kLayers - 1; li >= 0; --li) {
996	        const DecWeights::Layer& L = w.layer[li];
997	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
998	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
999	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
1000	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
1001	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1002	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1003	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1004	        }
1005	        __syncthreads();
1006	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
1007	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
1008	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, L.ff2_w,
1009	                                           sc.work, dec::kDff, dec::kD, sA, sB);  // dgact [nrows,dff]
1010	        __syncthreads();
1011	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
1012	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1013	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1014	            sc.work[idx] = dff0;
1015	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
1016	        }
1017	        __syncthreads();
1018	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
1019	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
1020	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, L.ff0_w,
1021	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB);  // dx1_ffn [nrows,d]
1022	        __syncthreads();
1023	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1024	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1025	        __syncthreads();
1026	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
1027	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1028	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1029	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
1030	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
1031	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
1032	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1033	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
1034	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1035	        }
1036	        __syncthreads();
1037	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1038	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, L.out_w,
1039	                                           sc.work, dec::kD, dec::kD, sA, sB);  // dctx
1040	        __syncthreads();
1041	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
1042	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
1043	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
1044	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
1045	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
1046	        __syncthreads();
1047	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
1048	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
1049	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, L.in_w,
1050	                                           sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB);  // dx_in_attn
1051	        __syncthreads();
1052	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1053	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
1054	        __syncthreads();
1055	    }
1056	
1057	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 acts (bf16); the
1058	    //    tok/pos owner-scan (P2) reads dh0 by global token row. ──
1059	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1060	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
1061	    __syncthreads();
1062	}
