1064	// ════════════════════════════════════════════════════════════════════════
1065	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
1066	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
1067	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
1068	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
1069	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
1070	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
1071	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
1072	//
1073	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
1074	//  the contraction length K (T for per-position weights, B for the head).
1075	// ════════════════════════════════════════════════════════════════════════
1076	struct DecDwSpec {
1077	    const __nv_bfloat16* dY;   // [K, Nout]
1078	    const __nv_bfloat16* X;    // [K, Kin]
1079	    int Nout; int Kin; int K;
1080	    int grad_off;              // element offset of this weight in `grad`
1081	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1082	    int bias_off;              // element offset of the bias in `grad`
1083	};
1084	
1085	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
1086	__device__ __forceinline__ void dectc_build_dw_specs(
1087	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
1088	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
1089	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
1090	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
1091	    //   head: out_w=28 (out_b=29)
1092	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
1093	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1094	    for (int s = 0; s < 8; ++s) {
1095	        const int li = s / 4, kind = s % 4;
1096	        DecDwSpec& sp = spec[s];
1097	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1098	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1099	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1100	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1101	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1102	        sp.dY_bias = sp.dY;
1103	    }
1104	    DecDwSpec& hd = spec[8];
1105	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1106	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1107	}
1108	
1109	// Total number of 64×N dW output tiles across the 9 weights (for the tile loop).
1110	template <int N>
1111	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1112	    int n = 0;
1113	    for (int s = 0; s < 9; ++s)
1114	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1115	    return n;
1116	}
1117	
1118	// Run ONE global dW tile `gt` (if it belongs to this CTA): decode (weight, M-atom,
1119	// N-tile), then contract K via the dW GEMM into grad[grad_off]. MaxAtomsM=1.
1120	template <int N>
1121	__device__ __forceinline__ void dectc_dw_run_tile(
1122	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1123	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1124	    // Decode gt → (s, m_atom, n_tile).
1125	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1126	    for (s = 0; s < 9; ++s) {
1127	        const int ma = (spec[s].Nout + 63) / 64;
1128	        const int nt = (spec[s].Kin + N - 1) / N;
1129	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1130	        acc += ma * nt;
1131	    }
1132	    const DecDwSpec& sp = spec[s];
1133	    const int mbase = m_atom * 64;
1134	    const int n0 = n_tile * N;
1135	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1136	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1137	    const int Nout = sp.Nout, Kin = sp.Kin;
1138	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1139	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase, m_atoms=1) passes the
1140	    // GLOBAL row m = mbase + mn to srcA/out (it adds mbase0 itself), so the
1141	    // accessors use `m` RAW — adding mbase again would double-count (the selftest
1142	    // passes mbase0=0 and uses m raw; we pass mbase0=mbase and likewise use m raw).
1143	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1144	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1145	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1146	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1147	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1148	    auto out  = [&] (int m, int n, float v) {
1149	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1150	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1151	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1152	}
1153	
1154	// ════════════════════════════════════════════════════════════════════════
1155	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
1156	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
1157	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
1158	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
1159	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
1160	//  reduce sums the G partials into grad — no float atomics, fixed order, so
1161	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
1162	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
1163	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
1164	//  kc) at dw_part[((gt*G+kc)) * (64*kDecMaxTileN) + row*kDecMaxTileN + col].
1165	//  Decoder K varies per spec: layer dW K=T, head dW K=B (so kc_steps reads sp.K).
1166	// ════════════════════════════════════════════════════════════════════════
1167	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
1168	constexpr int kDecDwTileFloats = wgs::kWgmmaAtomM * kDecMaxTileN;   // 64*N per (gt,kc) slot
1169	
1170	// COMPILE-TIME max #dW output tiles (the 9 dW have fixed Nout/Kin; decoder dims
1171	// are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff×d),
1172	// ff2(d×dff), N=kDecMaxTileN; + head(V×d).
1173	constexpr int kDecDwTilesPerLayer =
1174	      ((3*dec::kD + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
1175	    + ((dec::kD   + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
1176	    + ((dec::kDff + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
1177	    + ((dec::kD   + 63)/64) * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
1178	constexpr int kDecDwHeadTiles =
1179	      ((dec::kVocab + 63)/64) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
1180	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
1181	
1182	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
1183	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
1184	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
1185	}
1186	
1187	// Decode global dW tile index gt → (spec index s, m_atom, n_tile). Single-source.
1188	template <int N>
1189	__device__ __forceinline__ void dectc_dw_decode(
1190	        const DecDwSpec spec[9], int gt, int& s, int& m_atom, int& n_tile) {
1191	    int acc = 0;
1192	    for (s = 0; s < 9; ++s) {
1193	        const int ma = (spec[s].Nout + 63) / 64;
1194	        const int nt = (spec[s].Kin + N - 1) / N;
1195	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; return; }
1196	        acc += ma * nt;
1197	    }
1198	    s = 8; m_atom = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1199	}
1200	
1201	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
1202	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
1203	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
1204	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
1205	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
1206	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
1207	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
1208	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
1209	template <int N>
1210	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
1211	        const DecDwSpec spec[9], int gt, int kc, int G, float* __restrict__ dw_part,
1212	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1213	    int s, m_atom, n_tile;
1214	    dectc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1215	    const DecDwSpec& sp = spec[s];
1216	    const int mbase = m_atom * 64;
1217	    const int n0 = n_tile * N;
1218	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
1219	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
1220	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1221	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
1222	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
1223	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
1224	    // uninitialized accumulator → zero the slot + return instead of running it
1225	    // (the reduce sums all G slots unconditionally, so an empty chunk MUST be 0).
1226	    if (kc_steps <= 0) {
1227	        for (int i = threadIdx.x; i < 64 * N; i += blockDim.x) slot[i] = 0.0f;
1228	        __syncthreads();
1229	        return;
1230	    }
1231	    const int Nout = sp.Nout, Kin = sp.Kin;
1232	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1233	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1234	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1235	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1236	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1237	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it); the slot holds only this
1238	    // atom's 64 LOCAL rows → index by (m - mbase). A `m<64` guard would never fire
1239	    // for m_atom>=1 → that slot stays UNWRITTEN (the rel~1.0 dW bug). Local-row fills it.
1240	    auto out  = [&] (int m, int n, float v) {
1241	        const int lr = m - mbase;
1242	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1243	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1244	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1245	}
1246	
1247	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
1248	// → grad. Same (gt → geometry) decode as the partial.
1249	template <int N>
1250	__device__ __forceinline__ void dectc_dw_reduce_splitk(
1251	        const DecDwSpec spec[9], int n_dw, int G, const float* __restrict__ dw_part,
1252	        float* __restrict__ grad, int cta, int nCTA) {
1253	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1254	        int s, m_atom, n_tile;
1255	        dectc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1256	        const DecDwSpec& sp = spec[s];
1257	        const int mbase = m_atom * 64;
